export const POOL = [{"q":"What is the Bitcoin price right now?","kind":"live","intent":"price","topics":["charts","market_cap"],"words":"price usd dollar"},{"q":"What are Bitcoin fees right now?","kind":"live","intent":"fees","topics":["transaction_fees","vbyte"],"words":"fee fees sat vbyte"},{"q":"What is the current block height?","kind":"live","intent":"height","topics":["blockchain-timechain","block_time-block-size"],"words":"block height timechain"},{"q":"When is the next Bitcoin halving?","kind":"live","intent":"halving","topics":["scarce","mining"],"words":"halving countdown subsidy"},{"q":"What is the Bitcoin hashrate today?","kind":"live","intent":"hashrate","topics":["mining","0_mining__hashing"],"words":"hashrate hash rate"},{"q":"What is the mining difficulty right now?","kind":"live","intent":"difficulty","topics":["difficulty-adjustment","mining"],"words":"difficulty retarget"},{"q":"Is the Bitcoin mempool busy right now?","kind":"live","intent":"mempool","topics":["transaction_fees","blockchain-timechain"],"words":"mempool unconfirmed"},{"q":"How many bitcoin have been mined?","kind":"live","intent":"supply","topics":["scarce","money"],"words":"supply mined circulating"},{"q":"What is Bitcoin's all-time high?","kind":"live","intent":"ath","topics":["charts","cyles"],"words":"ath all time high"},{"q":"How much did Bitcoin change in 24 hours?","kind":"live","intent":"change24h","topics":["charts","ta_tips"],"words":"change 24h daily"},{"q":"What is 1 Bitcoin in euros?","kind":"live","intent":"price","currency":"EUR","topics":["charts"],"words":"euro eur price"},{"q":"What is 1 Bitcoin in pounds?","kind":"live","intent":"price","currency":"GBP","topics":["charts"],"words":"pound gbp price"},{"q":"What is 1 Bitcoin in yen?","kind":"live","intent":"price","currency":"JPY","topics":["charts"],"words":"yen jpy price"},{"q":"What is a satoshi?","kind":"kb","topics":["sats__or__bits","money"],"words":"satoshi sat sats","answer":"A satoshi is the smallest unit of Bitcoin. One bitcoin is 100 million sats."},{"q":"What is Bitcoin?","kind":"kb","topics":["one-stop-shop","money"],"words":"bitcoin beginner what","answer":"Bitcoin is digital money with a fixed supply of 21 million. No bank or government controls it."},{"q":"How does Bitcoin mining work?","kind":"kb","topics":["mining","0_mining__hashing"],"words":"mining miner sha nonce","answer":"Miners hash block data plus a nonce through SHA-256 until the result is low enough. It is a brute-force lottery, not a math puzzle."},{"q":"What is the Lightning Network?","kind":"kb","topics":["layer-2-lightning","lightning_node"],"words":"lightning payment channel","answer":"The Lightning Network is a Bitcoin layer for instant, low-fee payments that settle on the main chain."},{"q":"Why is self-custody important?","kind":"kb","topics":["self-custody","public_key_vs_private_key"],"words":"custody wallet keys","answer":"Self-custody means you hold the keys. Not your keys, not your coins: an exchange balance is someone else's promise."},{"q":"What is a seed phrase?","kind":"kb","topics":["self-custody","derivation_path"],"words":"seed phrase backup mnemonic","answer":"A seed phrase is the backup word list that can restore a wallet. Never type it into a website or chat."},{"q":"What is proof of work?","kind":"kb","topics":["pow-vs-pos","mining"],"words":"proof work energy","answer":"Proof of work makes adding blocks expensive in energy and hardware, so rewriting history is costly."},{"q":"Why is the supply capped at 21 million?","kind":"kb","topics":["scarce","money"],"words":"supply cap scarce million","answer":"The protocol only allows 21 million bitcoin. The cap is enforced by nodes, not by a company."},{"q":"What is a Bitcoin node?","kind":"kb","topics":["nodes","consensus"],"words":"node verify consensus","answer":"A full node checks every block against the rules. Don't trust, verify."},{"q":"What is the Bitcoin whitepaper?","kind":"kb","topics":["whitepaper","satoshi-nakamoto"],"words":"whitepaper satoshi paper","answer":"The Bitcoin whitepaper is the 2008 paper by Satoshi Nakamoto that describes peer-to-peer electronic cash."},{"q":"What is time preference?","kind":"kb","topics":["time_preference","austrian_school_of_economics"],"words":"time preference saving","answer":"Time preference is how much you value spending now versus later. Sound money rewards waiting."},{"q":"What is dollar-cost averaging?","kind":"kb","topics":["investment-strategy","charts"],"words":"dca dollar cost averaging","answer":"Dollar-cost averaging means buying a fixed amount on a schedule, instead of trying to time the market. Not financial advice."},{"q":"What is a UTXO?","kind":"kb","topics":["utxos","blockchain-timechain"],"words":"utxo unspent output","answer":"A UTXO is an unspent transaction output. Bitcoin tracks those coins, not account balances."},{"q":"What is Taproot?","kind":"kb","topics":["taproot","cryptography"],"words":"taproot schnorr","answer":"Taproot is a Bitcoin upgrade that uses Schnorr signatures and makes complex spends look simpler."},{"q":"What is the difficulty adjustment?","kind":"kb","topics":["difficulty-adjustment","mining"],"words":"difficulty adjustment retarget","answer":"Every 2016 blocks, Bitcoin retargets difficulty so blocks stay near ten minutes apart."},{"q":"What is a transaction fee?","kind":"kb","topics":["transaction_fees","vbyte"],"words":"transaction fee sat vbyte","answer":"A transaction fee is what you pay miners, usually priced in satoshis per virtual byte."},{"q":"Who created Bitcoin?","kind":"kb","topics":["satoshi-nakamoto","history","whitepaper"],"words":"satoshi nakamoto creator","answer":"Bitcoin was created by Satoshi Nakamoto, who published the whitepaper in 2008 and then stepped away."},{"q":"What is the halving?","kind":"kb","topics":["scarce","mining"],"words":"halving subsidy reward","answer":"The halving cuts the new-coin subsidy in half every 210,000 blocks, about every four years."},{"q":"What does not your keys, not your coins mean?","kind":"kb","topics":["self-custody"],"words":"keys coins custody","answer":"If someone else holds the keys, they control the bitcoin. Self-custody means the keys are yours."},{"q":"What is the mempool?","kind":"kb","topics":["transaction_fees","blockchain-timechain"],"words":"mempool unconfirmed","answer":"The mempool is the set of valid transactions a node has seen but that are not in a block yet."},{"q":"How do Bitcoin addresses work?","kind":"kb","topics":["blockchain-timechain","public_key_vs_private_key"],"words":"address public key","answer":"An address is a shareable destination derived from a key. The private key is what spends the coins."},{"q":"What is Satoshi's Favor?","kind":"app","id":"favor","topics":["mining"],"words":"favor satoshi hash game","answer":"Satoshi's Favor is the in-app hashing game. Points from quests, level-ups, and badges can open a mining window."},{"q":"How do I earn XP on Bitcoin Quest?","kind":"app","id":"quests","topics":["one-stop-shop"],"words":"xp experience quest","answer":"XP is experience in the app. Daily gains are full through 500, half through 900, then a quarter until the shared 1,000 cap."},{"q":"How do raffles work here?","kind":"app","id":"raffle","topics":["games"],"words":"raffle ticket orange","answer":"Orange Tickets can enter the sats raffle. Draws are announced in Global Chat."},{"q":"What is the Quest Hub?","kind":"app","id":"quests","topics":["one-stop-shop"],"words":"quest hub quiz trivia","answer":"Quest Hub is where quizzes, trivia, polls, Flex, and Satoshi's Favor live."},{"q":"How do I turn on two-factor auth?","kind":"app","id":"security","topics":["self-custody"],"words":"2fa authenticator security","answer":"Open Settings and turn on an authenticator. This device can be remembered for 30 days. Sensitive changes still ask for a fresh code."},{"q":"What are Orange Tickets?","kind":"app","id":"raffle","topics":["games"],"words":"orange tickets shop nook","answer":"Orange Tickets are the shop currency. You can earn them from the daily spin, activity, and referrals."},{"q":"What is the daily quiz?","kind":"app","id":"quiz","topics":["curriculum"],"words":"quiz daily question","answer":"The daily quiz is a short Bitcoin question in Quest Hub. The server checks the reward."},{"q":"How do gifts work in the app?","kind":"app","id":"gifts","topics":["one-stop-shop"],"words":"gift gifts send","answer":"Gifts let you send an in-app gift to another member. Open the gifts page to send or receive one."},{"q":"What is Proof of Walk?","kind":"app","id":"proof-of-walk","topics":["health"],"words":"walk strava steps","answer":"Proof of Walk connects a walk or run and can earn XP, with a daily cap."},{"q":"Where do I start if I am brand new?","kind":"app","id":"one-stop-shop","topics":["one-stop-shop","whitepaper"],"words":"beginner start new","answer":"Start with the One Stop Shop channel. It is the short path into the rest of the archive."}];
